query GetPropertyDefinitionOfExchange($exchangeId: ID!) {
    exchange(exchangeId: $exchangeId) {
        id
        name
        alternativeIdentifiers {
            fileUrn
            fileVersionUrn
        }
        propertyDefinitions {
            results {
                id
                name
                units {
                    name
                }
            }
        }
    }
}

